package cn.hospital.rehab.common.audit;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;
@Service public class AuditLogService {private final JdbcClient jdbc;private final ObjectMapper mapper;public AuditLogService(JdbcClient jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}
 public void record(Authentication auth,String module,String type,String businessId,String action,Object before,Object after){record(auth,module,type,businessId,action,before,after,null);}
 public void record(Authentication auth,String module,String type,String businessId,String action,Object before,Object after,String clientIp){try{String b=before==null?null:mapper.writeValueAsString(before),a=after==null?null:mapper.writeValueAsString(after);jdbc.sql("INSERT INTO operation_audit_log(module_code,business_type,business_id,action_type,operator_name,before_data,after_data,client_ip) VALUES(:module,:type,:id,:action,:operator,CAST(:before AS jsonb),CAST(:after AS jsonb),:clientIp)").param("module",module).param("type",type).param("id",businessId).param("action",action).param("operator",auth==null?"system":auth.getName()).param("before",b).param("after",a).param("clientIp",clientIp).update();}catch(JsonProcessingException e){throw new IllegalStateException("审计数据序列化失败",e);}}
}
